package vn.svframe.svframelib.api.crafting.ingredients; import java.util.*; public class SVFrameBlueprintInventory { private final SVFrameRecipeInventory main,result; private final Map<String,SVFrameRecipeInventory> side=new LinkedHashMap<>(); public SVFrameBlueprintInventory(SVFrameRecipeInventory main,SVFrameRecipeInventory result){this.main=main;this.result=result;} public SVFrameRecipeInventory getMainInventory(){return main;} public SVFrameRecipeInventory getResultInventory(){return result;} public SVFrameRecipeInventory getSideInventory(String n){return side.get(n);} public boolean hasSideInventories(String n){return side.containsKey(n);} public ArrayList<String> getSideInventoryNames(){return new ArrayList<>(side.keySet());} public void addSideInventory(String n,SVFrameRecipeInventory i){side.put(n,i);} public void clearSideInventories(){side.clear();} public SVFrameBlueprintInventory cloneInventory(){SVFrameBlueprintInventory b=new SVFrameBlueprintInventory(main.clone(),result.clone());side.forEach((k,v)->b.addSideInventory(k,v.clone()));return b;} }
